#include "vrm-rest-consumer-fixtures.hpp"
#include "bone-metadata.hpp"
namespace {
void mark_source_nodes(const std::filesystem::path&file){
 std::ifstream in(file,std::ios::binary);std::vector<uint8_t>b{std::istreambuf_iterator<char>(in),{}};const size_t size=vrm_source_fixture::word(b,12);auto j=nlohmann::json::parse(b.begin()+20,b.begin()+20+size);std::vector<uint8_t>tail(b.begin()+20+size,b.end());for(size_t n=0;n<j["nodes"].size();++n)j["nodes"][n]["extras"]["independentOriginalIndex"]=n;auto text=j.dump();while(text.size()%4)text+=' ';std::vector<uint8_t>output;auto put=[&](uint32_t v){for(int k=0;k<4;++k)output.push_back(uint8_t(v>>(8*k)));};put(0x46546c67);put(2);put(uint32_t(20+text.size()+tail.size()));put(uint32_t(text.size()));put(0x4e4f534a);output.insert(output.end(),text.begin(),text.end());output.insert(output.end(),tail.begin(),tail.end());std::ofstream out(file,std::ios::binary);out.write(reinterpret_cast<const char*>(output.data()),output.size());
}
void reimport(const Scene&before,const std::filesystem::path&file,float expected_length){
 ImportAuthoringOptions options;options.paint_resolution=64;
 auto adopted=prepare_authoring_import(Scene{},file,options);
 check(adopted.objects.size()==std::count_if(before.objects().begin(),before.objects().end(),[](const auto&o){return bool(o.appearance);}),"Fresh native import adopts every exported real skin and rigid part without raising hierarchy limits");
 cgltf_options cg{};cgltf_data*raw=nullptr;if(cgltf_parse_file(&cg,file.c_str(),&raw)!=cgltf_result_success)throw std::runtime_error("Independent roundtrip parse failed");std::unique_ptr<cgltf_data,decltype(&cgltf_free)>owner(raw,cgltf_free);if(cgltf_load_buffers(&cg,raw,file.c_str())!=cgltf_result_success)throw std::runtime_error("Independent roundtrip buffers failed");
 auto j=nlohmann::json::parse(raw->json,raw->json+raw->json_size);size_t head=SIZE_MAX;for(const auto&b:j.at("extensions").at("VRM").at("humanoid").at("humanBones"))if(b.at("bone").get_ref<const std::string&>()=="head")head=b.at("node").get<size_t>();
 const auto first=std::find_if(before.objects().begin(),before.objects().end(),[](const auto&o){return bool(o.appearance);});if(first==before.objects().end())throw std::runtime_error("No source fixture owner");const auto &source=*first->appearance->asset;
 std::vector<size_t>emitted(source.nodes.size(),SIZE_MAX);
 for(size_t n=0;n<j["nodes"].size();++n){auto&node=j["nodes"][n];if(node.contains("extras")&&node.at("extras").is_object()&&node.at("extras").contains("independentOriginalIndex")){auto id=node.at("extras").at("independentOriginalIndex").get<size_t>();if(id>=emitted.size()||emitted[id]!=SIZE_MAX)throw std::runtime_error("Lost/duplicated actual original source node identity");emitted[id]=n;}}
 for(size_t id=0;id<source.nodes.size();++id){if(emitted[id]==SIZE_MAX)throw std::runtime_error("A real original source node was dropped");std::vector<size_t>actual;auto&node=j["nodes"][emitted[id]];if(node.contains("children"))for(auto child:node.at("children")){auto&value=j["nodes"].at(child.get<size_t>());if(value.contains("extras")&&value.at("extras").is_object()&&value.at("extras").contains("independentOriginalIndex"))actual.push_back(value.at("extras").at("independentOriginalIndex").get<size_t>());}if(actual!=std::vector<size_t>(source.nodes[id].children.begin(),source.nodes[id].children.end()))throw std::runtime_error("Actual original source ordered child identities changed");}
 check(true,"Every real source node survives once, with exact original ordered child identity and unrelated opaque extras");
 check(head<raw->nodes_count && detail::bone_length_record(j.at("nodes").at(head).at("extras"))==expected_length,"Actual exported humanoid node carries the exact typed localY length");
 double worst=0;size_t corners=0,slots=0;auto surfaces=adopted.scene.surfaces();
 for(const auto&surface:surfaces){const auto&a=*surface.appearance;auto&node=raw->nodes[a.source_node];auto mesh=surface.preview_mesh();const auto world=surface.world_matrix();auto&primitive=node.mesh->primitives[a.source_primitive];
  if(surface.deformation&&surface.deformation->skin){const auto&d=*surface.deformation;
   for(size_t declared=0;declared<node.skin->joints_count;++declared){const auto source_joint=uint32_t(node.skin->joints[declared]-raw->nodes);const auto at=std::find(a.source_joint_nodes.begin(),a.source_joint_nodes.end(),source_joint);if(at==a.source_joint_nodes.end()||a.asset->skins.at(size_t(a.asset->nodes.at(a.source_node).skin)).joints.at(declared)!=source_joint)throw std::runtime_error("Immutable raw skin joint-table order/actual source identity lost during placement adoption");float bind[16];if(!cgltf_accessor_read_float(node.skin->inverse_bind_matrices,declared,bind,16))throw std::runtime_error("Raw declared source IBM missing");const auto&own=d.skeleton->inverse_bind_override->at(size_t(at-a.source_joint_nodes.begin()));for(size_t k=0;k<16;++k)if(std::bit_cast<uint32_t>(bind[k])!=std::bit_cast<uint32_t>(own[k]))throw std::runtime_error("Actual raw own IBM bits changed during derived placement adoption");}
const auto at=std::find(a.source_joint_nodes.begin(),a.source_joint_nodes.end(),head);check(at!=a.source_joint_nodes.end(),"Fresh native skin uses the actual emitted humanoid source ID, never a name or presumed slot");const auto slot=size_t(at-a.source_joint_nodes.begin());check(d.skeleton->bones.at(slot).length==expected_length,"Every native shared skin restores its own exact length slot");++slots;}
  if(!primitive.indices || primitive.indices->count!=mesh.indices.size())throw std::runtime_error("Reimport ordered corners mismatch");
  for(size_t c=0;c<mesh.indices.size();++c){auto p=mesh.positions[mesh.indices[c]];auto w=world.point({p.x,p.y,p.z});auto actual=consume(node,cgltf_accessor_read_index(primitive.indices,c));auto e=double(length(actual-Vec3{float(w[0]),float(w[1]),float(w[2])}));worst=std::max(worst,e);if(e>2e-5)throw std::runtime_error("Fresh native evaluated own-skin pose differs from independent emitted consumer");++corners;}
 }
 check(slots==19&&corners>40000,"All real per-part own-skin and rigid corner geometry survives fresh native import");
 auto save=file;save.replace_extension("dsculpt");adopted.scene.save(save);auto restarted=Scene::load(save);check(restarted.encode()==adopted.scene.encode(),"Freshly imported lengths, source identity, own IBM and metadata survive native Save/restart exactly");
 auto edited=restarted;const auto selected=adopted.objects.front();const auto joint=edited.object(selected).deformation->humanoid->joints.at("head");RigRestJointEdit edit;edit.joint=joint;edit.world_length=.119f;author_rig_rest(edited,selected,{&edit,1});check(bool(edited.object(selected).rig_source),"Freshly reimported source can be edited with a complete first rig source capsule");restore_rig_source(edited,selected);check(edited.encode()==restarted.encode(),"Length-only Restore returns the complete freshly imported native state byte-exactly");author_rig_rest(edited,selected,{&edit,1});RigEdit pose;pose.joint=JointAdjustment{joint,{0,0,7},{}};edit_rig(edited,selected,pose);auto edited_file=file.parent_path()/(file.stem().string()+"-native-edited.vrm");verify_vrm(edited,selected,edited_file);restore_rig_source(edited,selected);auto expected=restarted.encode(),actual=edited.encode();
 for(size_t i=0;i<restarted.objects().size();++i){const auto&id=restarted.objects()[i].id;const auto a=restarted.world_matrix(id).matrix(),b=edited.world_matrix(id).matrix();for(size_t k=0;k<16;++k)if(std::abs(a[k]-b[k])>1e-11)throw std::runtime_error("Post-pose Restore changed actual world placement rather than only redundant double identity representation");actual["objects"][i]["affine_edit"]=expected["objects"][i]["affine_edit"];}
 actual["affine_state"]=expected["affine_state"];check(actual==expected,"Post-pose Restore preserves every source/paint/skin/morph/role and non-placement native field exactly; full world transforms remain within tight double reconstruction bounds");
 std::cout<<file.filename().string()<<" fresh-native-groups="<<adopted.scene.groups().size()<<" corners="<<corners<<" world_max="<<worst<<'\n';
}
}
int main(int argc,char**argv)try{
 if(argc!=4)return 2;const auto dir=std::filesystem::path(argv[3]);std::filesystem::create_directories(dir);
 for(size_t base=0;base<2;++base){auto stem=std::to_string(base);auto placed=dir/(stem+"-placed.vrm"),input=dir/(stem+"-input.vrm");vrm_source_fixture::source_variant(argv[base+1],placed,2);vrm_source_fixture::with_rigid_accessories(placed,input);mark_source_nodes(input);ImportAuthoringOptions options;options.paint_resolution=64;auto prepared=prepare_authoring_import(Scene{},input,options);
  for(bool metric:{false,true}){auto scene=prepared.scene;auto selected=prepared.objects.front();if(metric){auto identity=detail::source_rest_identity(scene,scene.object(selected));scene.group(identity->source_instance).affine_edit=std::make_shared<const NativeAffineEdit>(AffineTransform(std::array<double,16>{-1.1,0,0,0,.2,.9,0,0,.1,.05,1.2,0,.3,-.1,.2,1}));}auto head=scene.object(selected).deformation->humanoid->joints.at("head");RigRestJointEdit length;length.joint=head;length.world_length=.137f;author_rig_rest(scene,selected,{&length,1});float expected=scene.object(selected).deformation->skeleton->bones[head].length;
   for(bool posed:{false,true}){if(posed){RigEdit pose;pose.joint=JointAdjustment{head,{0,0,13},{}};edit_rig(scene,selected,pose);}auto path=dir/(stem+"-"+(metric?"reflected":"ordinary")+"-"+(posed?"posed":"rest")+".vrm");verify_vrm(scene,selected,path);reimport(scene,path,expected);}
  }
 }
 std::cout<<checks<<" actual bone-length/export/fresh-native checks passed\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
